#include "common.hpp"
static constexpr uint32_t TH[4]={1,10,50,100};
inline uint8_t goodmask(uint32_t f){return uint8_t(f<=1)|(uint8_t(f<=10)<<1)|(uint8_t(f<=50)<<2)|(uint8_t(f<=100)<<3);}
struct WInfo{std::vector<uint8_t> good,mixed,allA;U nwin=0,feasible[4]={},mixed_n[4]={},allA_n=0;};
struct Node{U pos,value;};
WInfo windowinfo(const Record&r,int w){WInfo z;z.good.resize(r.x.size());z.mixed.resize(r.x.size());z.allA.resize(r.x.size());size_t cap=1;while(cap<=size_t(w))cap*=2;std::vector<Node>qn(cap),qx(cap);U cm=cap-1;for(auto b:r.blocks){U h=0,t=0,H=0,T=0,nzero=0;for(U i=b.beg;i<b.end;i++){U v=r.freq[i];while(t>h&&qn[(t-1)&cm].value>v)--t;qn[(t++)&cm]={i,v};while(T>H&&qx[(T-1)&cm].value<v)--T;qx[(T++)&cm]={i,v};if(t>h&&qn[h&cm].pos+U(w)<=i)++h;if(T>H&&qx[H&cm].pos+U(w)<=i)++H;nzero+=(r.x[i]==0);if(i>=b.beg+U(w))nzero-=(r.x[i-w]==0);if(i+1<b.beg+U(w))continue;uint8_t g=goodmask(qn[h&cm].value),bad=uint8_t(~goodmask(qx[H&cm].value))&15;z.good[i]=g;z.mixed[i]=g&bad;z.allA[i]=nzero>0;z.allA_n+=(nzero>0);++z.nwin;for(int a=0;a<4;a++){z.feasible[a]+=(g>>a)&1;z.mixed_n[a]+=((g&bad)>>a)&1;}}}return z;}
void evaluate(const Record&r,const WInfo&sw,const WInfo&ew,const std::string&method,U seed,int w,int E,int tie,const std::string&label,const std::string&record,std::ostream&out,bool distinct){
Hasher hash(method,r.k,seed);std::vector<uint8_t>selected(r.x.size(),0);size_t cap=1;while(cap<=size_t(w))cap*=2;std::vector<Node>q(cap);U cm=cap-1,nsel=0,nlow=0,nhom=0,sumfreq=0,maxfreq=0,selHigh[4]={},av[4]={},winhi[4]={},keptsum[4]={},allaselect=0,score_calls=0;std::vector<U>keys;if(distinct)keys.reserve(r.x.size()/5+1);
for(auto b:r.blocks){U h=0,t=0,prev=~U(0),prevscore=0;for(U i=b.beg;i<b.end;i++){U score=hash(r.x[i]);++score_calls;while(t>h&&(tie>0?q[(t-1)&cm].value>=score:q[(t-1)&cm].value>score))--t;q[(t++)&cm]={i,score};if(t>h&&q[h&cm].pos+U(w)<=i)++h;if(i+1<b.beg+U(w))continue;U p=q[h&cm].pos;U best=q[h&cm].value;if(tie==2&&prev!=~U(0)&&prev+U(w)>i&&prevscore==best)p=prev;
uint32_t f=r.freq[p];uint8_t bad=uint8_t(~goodmask(f))&15;if(bad){uint8_t am=sw.mixed[i]&bad;for(int a=0;a<4;a++){winhi[a]+=(bad>>a)&1;av[a]+=(am>>a)&1;}}
allaselect+=(sw.allA[i]&&r.x[p]==0);
if(p!=prev){if(selected[p])throw std::runtime_error("selected coordinate revisited");selected[p]=1;++nsel;nlow+=r.flags[p]&1;nhom+=(r.flags[p]>>1)&1;sumfreq+=f;maxfreq=std::max<U>(maxfreq,f);for(int a=0;a<4;a++){selHigh[a]+=f>TH[a];if(f<=TH[a])keptsum[a]+=f;}if(distinct)keys.push_back(r.x[p]);}prev=p;prevscore=best;}}
U covered[4]={},maxrun[4]={};
for(auto b:r.blocks){int64_t last[4]={-1,-1,-1,-1};U run[4]={};for(U i=b.beg;i<b.end;i++){if(selected[i]){uint32_t f=r.freq[i];for(int a=0;a<4;a++)if(f<=TH[a])last[a]=int64_t(i);}if(i+1<b.beg+U(E))continue;int64_t start=int64_t(i)-E+1;uint8_t g=ew.good[i];for(int a=0;a<4;a++){bool cv=last[a]>=start;bool feas=(g>>a)&1;if(cv&&!feas)throw std::runtime_error("covered infeasible");covered[a]+=cv;if(feas&&!cv){++run[a];maxrun[a]=std::max(maxrun[a],run[a]);}else run[a]=0;}}}
U uniq=0;if(distinct){std::sort(keys.begin(),keys.end());uniq=std::unique(keys.begin(),keys.end())-keys.begin();}
for(int a=0;a<4;a++){if(av[a]>sw.mixed_n[a]||covered[a]>ew.feasible[a]||selHigh[a]>nsel)throw std::runtime_error("invariant");out<<label<<','<<record<<",canonical,"<<r.k<<','<<method<<','<<seed<<','<<hash.salt<<','<<hash.a<<','<<hash.b<<','<<w<<','<<TH[a]<<','<<(tie==0?"left":tie==1?"right":"robust")<<','<<r.x.size()<<','<<sw.nwin<<','<<nsel<<',';if(distinct)out<<uniq;out<<','<<selHigh[a]<<','<<nlow<<','<<nhom<<','<<sumfreq<<','<<maxfreq<<','<<sw.mixed_n[a]<<','<<av[a]<<','<<sw.feasible[a]<<','<<winhi[a]<<','<<sw.allA_n<<','<<allaselect<<','<<E<<','<<ew.nwin<<','<<ew.feasible[a]<<','<<covered[a]<<','<<maxrun[a]<<','<<keptsum[a]<<','<<score_calls<<'\n';}
}
int main(int argc,char**argv){try{std::unordered_map<std::string,std::string>a;for(int i=1;i<argc;i+=2){if(i+1>=argc)throw std::runtime_error("missing arg");a[argv[i]]=argv[i+1];}auto get=[&](const std::string&s,const std::string&d){return a.count(s)?a[s]:d;};fixed_config_dir=get("--configs","configs");auto r=load_record(a.at("--cache"));std::string label=a.at("--label"),rec=a.at("--record"),outfile=a.at("--out");auto seeds=ints(get("--seeds","42"));auto ws=ints(get("--ws","20"));auto methods=strings(get("--methods","kssd_repo,xor,mul,mul64,affine,affine64,salted_mul,salted_mul64,mix64,minimap_hash,identity"));int E=std::stoi(get("--eval-w","20"));std::string ts=get("--tie","left");int tie=ts=="left"?0:ts=="right"?1:ts=="robust"?2:-1;if(tie<0)throw std::runtime_error("tie");bool distinct=get("--distinct","0")=="1";std::ofstream out(outfile);if(!out)throw std::runtime_error("cannot write");out<<"dataset,record,mode,k,method,hash_seed,salt,a,b,w,tau,tie,n_eligible,n_windows,n_selected,n_unique_selected_record,n_selected_highfreq,n_selected_lowentropy,n_selected_homopolymer,sum_reference_frequency,max_selected_frequency,n_mixed_windows,n_avoidable_highfreq,n_feasible_sampling_windows,n_windows_select_highfreq,n_windows_with_allA,n_windows_select_allA,eval_w,n_eval_windows,n_eval_feasible,n_eval_covered,max_uncovered_feasible_run,sum_retained_reference_frequency,n_hash_calls\n";
auto ew=windowinfo(r,E);for(int w:ws){if(w<1||E<1)throw std::runtime_error("window");WInfo sw0;const WInfo*sw=&ew;if(w!=E){sw0=windowinfo(r,w);sw=&sw0;}for(auto&m:methods){auto ss=seeds;auto start=std::chrono::steady_clock::now();for(int s:ss){evaluate(r,*sw,ew,m,s,w,E,tie,label,rec,out,distinct);}out.flush();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::cerr<<label<<' '<<rec<<" k="<<r.k<<" w="<<w<<' '<<m<<" seeds="<<ss.size()<<" diagnostic_seconds="<<sec<<'\n';}}
return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
